// Temporary compatibility fixture generated by the unchanged TypeScript storage implementations.
import { openHistory, readHistory } from "../history.js";
import { SimulatorAdapter } from "../simulator.js";
import { loadConfig } from "../config.js";
import type { MicrosipOrder } from "../contracts.js";
const directory = process.argv[3]!;
const c = loadConfig("config.example.json");
const id = "00000000-0000-4000-8000-000000000010";
if (process.argv[2] === "verify") {
  const entry = readHistory(directory, c.company, c.organizationId).find(e => e.orderId === id);
  if (entry?.status !== "synced" || entry.receipt?.folio !== "SIM-00000001") throw new Error(".NET fixture unreadable from TypeScript");
  console.log("TypeScript read .NET transition and receipt");
} else {
  const history = openHistory(directory, c.company, c.organizationId);
  const simulator = new SimulatorAdapter(directory);
  const payload: MicrosipOrder = { externalId: `vegyfresh:${c.organizationId}:${id}`, company: c.company,
    branch: c.branch, warehouse: c.warehouse, customerKey: Object.values(c.clients)[0]!,
    lines: [{ productKey: "FOLIO-01", unit: "KG", quantity: 1.125 }] };
  await simulator.create(payload);
  history.save({ orderId: "__adapter_identity__", externalId: "simulator", status: "synced", attempts: 0, updatedAt: new Date().toISOString() });
  history.save({ orderId: id, externalId: payload.externalId, status: "submitting", attempts: 1,
    updatedAt: new Date().toISOString(), payload });
  simulator.close(); history.close();
}
